import{_ as n,o as e,c as a,a5 as i}from"./chunks/framework.CsGesDJn.js";const s=JSON.parse('{"title":"09 — Admin Management","description":"","frontmatter":{},"headers":[],"relativePath":"ba/09-admin-management.md","filePath":"ba/09-admin-management.md"}'),h={name:"ba/09-admin-management.md"};function r(d,t,o,c,g,m){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="_09-—-admin-management" tabindex="-1">09 — Admin Management <a class="header-anchor" href="#_09-—-admin-management" aria-label="Permalink to &quot;09 — Admin Management&quot;">​</a></h1><p>&gt; <a href="./00-overview.html">&lt;&lt; Về Overview</a></p><h2 id="danh-sach-fr-đay-đu-3-10-1-–-3-10-12" tabindex="-1">Danh sách FR đầy đủ (3.10.1 – 3.10.12) <a class="header-anchor" href="#danh-sach-fr-đay-đu-3-10-1-–-3-10-12" aria-label="Permalink to &quot;Danh sách FR đầy đủ (3.10.1 – 3.10.12)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>FR</th><th>Tên</th><th>Mô tả</th></tr></thead><tbody><tr><td>3.10.1</td><td>Push Notification</td><td>Tạo thông báo toàn hệ thống, có phân chia theo nhóm user</td></tr><tr><td>3.10.2</td><td>Platform Statistics Overview</td><td>Dashboard tổng quan hệ thống — chart về user, doanh thu, agency đang hoạt động</td></tr><tr><td>3.10.3</td><td>System Health Monitoring</td><td>Xem tài nguyên server tại thời điểm hiện tại (%CPU, %RAM...) trong hệ thống microservice, server còn sống không</td></tr><tr><td>3.10.4</td><td>Content Moderation Queue</td><td>Hiển thị content của Creator bị dính chính sách kiểm duyệt — Admin check lại xem quyết định hệ thống đúng hay không</td></tr><tr><td>3.10.5</td><td>User Management (Verify/Disable/Delete)</td><td>Chuyển đổi trạng thái user trực tiếp — thiết kế để KHÔNG tách quá nhiều FR riêng lẻ</td></tr><tr><td>3.10.6</td><td>View User</td><td>Xem danh sách User trong hệ thống</td></tr><tr><td>3.10.7</td><td>Create User</td><td>Tạo User mới vào hệ thống</td></tr><tr><td>3.10.8</td><td>Update User</td><td>Chỉnh sửa thông tin User</td></tr><tr><td>3.10.9</td><td>Deactivate User</td><td>Tạm khóa Account người dùng</td></tr><tr><td>3.10.11</td><td>View Revenue Dashboard</td><td>Xem doanh thu hệ thống thu được từ Plan và Credit</td></tr><tr><td>3.10.12</td><td>Export Report File PDF</td><td>Xuất báo cáo cho các trang quản lý User, Revenue... dạng PDF</td></tr></tbody></table><p>Toàn bộ role: ADMIN. Admin tách biệt hoàn toàn khỏi cấu trúc Agency→Workspace — xem <a href="./01-organization-structure.html">01-organization-structure.md</a> mục 6.</p><p><strong>Lưu ý số hiệu FR</strong>: CSV gốc nhảy từ 3.10.9 sang 3.10.11 (không có 3.10.10) — giữ nguyên số hiệu như nguồn gốc, không tự đánh số lại để tránh lệch tham chiếu khi đối chiếu về sau.</p><h2 id="quyen-han-giua-cac-admin-confirmed-2026-09-17" tabindex="-1">Quyền hạn giữa các Admin [CONFIRMED 2026-09-17] <a class="header-anchor" href="#quyen-han-giua-cac-admin-confirmed-2026-09-17" aria-label="Permalink to &quot;Quyền hạn giữa các Admin [CONFIRMED 2026-09-17]&quot;">​</a></h2><p>CSV gốc tại FR 3.10.9 (Deactivate User) có note treo: &gt; &quot;admin có xoá được admin không? hệ thống có bao nhiêu admin?&quot;</p><p>Đã confirm với Trung:</p><ul><li><strong>Admin KHÔNG xóa/deactivate được Admin khác</strong> — không có phân cấp Super Admin trong phạm vi RBAC (mọi Admin ngang quyền, không ai override được Admin khác qua API).</li><li>Số lượng Admin: không giới hạn cứng trong hệ thống — việc tạo/gỡ Admin xử lý ngoài luồng RBAC ứng dụng (ví dụ: qua thao tác trực tiếp DB/vận hành nội bộ), không thuộc phạm vi feature cần code trong <code>docs/feature</code>.</li></ul><h2 id="content-moderation-queue-3-10-4-—-lien-ket-voi-compliance-check" tabindex="-1">Content Moderation Queue (3.10.4) — liên kết với Compliance Check <a class="header-anchor" href="#content-moderation-queue-3-10-4-—-lien-ket-voi-compliance-check" aria-label="Permalink to &quot;Content Moderation Queue (3.10.4) — liên kết với Compliance Check&quot;">​</a></h2><ul><li>FR này liên quan trực tiếp tới <strong>Check Compliance Content</strong> (FR 3.6.33, xem <a href="./05-content-task-workflow.html">05-content-task-workflow.md</a> mục 8) — khi hệ thống tự động phát hiện content vi phạm chính sách, nó vào hàng đợi Content Moderation Queue để Admin review lại quyết định (đúng/sai) của hệ thống tự động, không phải Admin tự kiểm duyệt từ đầu.</li></ul><h2 id="user-management-gop-fr-3-10-5" tabindex="-1">User Management gộp FR (3.10.5) <a class="header-anchor" href="#user-management-gop-fr-3-10-5" aria-label="Permalink to &quot;User Management gộp FR (3.10.5)&quot;">​</a></h2><ul><li>Thiết kế có chủ đích: <strong>không tách CRUD trạng thái user thành nhiều FR nhỏ</strong> (verify/disable/delete riêng lẻ) — gộp vào 1 FR &quot;chuyển đổi trạng thái&quot; để Admin điều chỉnh trực tiếp, giảm số lượng FR/API endpoint cần maintain.</li></ul>',14)])])}const l=n(h,[["render",r]]);export{s as __pageData,l as default};
